"""批注数据：src/tools/GrepTool/GrepTool.ts（577 行）"""

ANNOTATIONS = [
    (32, 'after', "Grep 工具本体：ripgrep 的受控封装。设计上最显眼的决定是——**输入参数名直接沿用 rg 的旗标**（-B / -A / -C / -n / -i），模型只要会 rg 就会调这个工具，文档成本近乎为零。"),
    (60, 'after', "参数值过 semanticNumber 而不是裸 z.number()：宽容模型把数字写成字符串（「3」也能过）。这类「语义宽容」解析是工具层的通用套路——模型的输出格式不可控，校验层负责收口。注意 -B/-A/-C 与 context 都要求 output_mode 为 content，否则被静默忽略。"),
    (70, 'after', "-n 默认 true——和原生 rg 相反（rg 默认不显示行号）。工具封装在「贴近原生命令」与「对模型友好」之间选了后者：带上行号，模型后续才能用 Edit 精确定位。"),
    (82, 'after', "head_limit 默认 250；显式传 0 是「不设限」的逃生门。英文注释解释了 250 的由来：不限量的 content 模式 grep 能填满 20KB 的结果落盘阈值（grep 重度会话实测 6-24K token），250 对探索式搜索足够宽裕。"),
    (88, 'after', "multiline 对应 rg 的 -U --multiline-dotall，默认关。跨行 pattern（如 struct 开括号到 field）才需要开；默认关是因为多行匹配又慢又容易拖回一大段无关上下文。"),
    (102, 'after', "六个 VCS 目录一律排除：.git / .svn / .hg / .bzr 之外还有 .jj（Jujutsu）和 .sl（Sapling）——两个新兴版本控制系统也在名单里。排除靠 --glob '!dir' 实现，因为它们只会给搜索结果添噪音。"),
    (108, 'after', "DEFAULT_HEAD_LIMIT = 250，与 head_limit 的默认值呼应。这里的核心权衡写在英文注释里：不设上限的 content grep 会一路填到 20KB 落盘阈值，250 是「探索够用且不撑爆上下文」的平衡点。"),
    (118, 'after', "显式传 0 = 无限。这是一个专门的逃生门：模型确信需要全量结果时可以自己选择付上下文的代价；默认路径永远是受限的。"),
    (128, 'after', "appliedLimit 只在真的发生截断时才返回——这是给模型的信号：「还有更多结果，可以用 offset 翻页」。如果没截断也返回 limit 值，模型会误以为后面还有而白跑一轮。"),
    (142, 'after', "formatLimitInfo 条件拼接，避免在用户可见输出里出现「limit: undefined」这种字样——appliedLimit 没截断时是 undefined，appliedOffset 为 0 时也不显示。工具结果的每个字段都要么有意义要么不出现。"),
    (164, 'after', "20,000 字符 = 工具结果落盘阈值（persist threshold）。这是刻意对齐的：超过阈值的工具结果不进上下文而是落盘让模型按需读回，Grep 的上限就设在这个临界点上。"),
    (165, 'after', "strict: true——到目前读过的工具里只有 Grep 声明了这个。入参 schema 有十几个字段且含 -B 这类非常规键名，开严格模式让 API 按 JSON Schema 校验生成参数，减少模型手滑传错字段名的情况。"),
    (191, 'after', "toAutoClassifierInput 把 pattern 和 path 拼给自动分类器判断意图——path 有无影响分类精度，所以条件拼接而不是永远只给 pattern。"),
    (210, 'after', "UNC 短路，与 Glob/FileReadTool 同一条安全规矩：Windows 上 stat 网络路径会发起 SMB 认证泄露 NTLM。注意 Grep 的 validateInput 不检查「是不是目录」——rg 的 PATH 允许直接是文件，这是它和 Glob 的有意分化。"),
    (216, 'after', "ENOENT 时同样做 suggestPathUnderCwd 补救，报错里带「Did you mean」。两个搜索工具、三个文件工具，错误提示里全都有这一手——模型拼错路径是最高频的错误，值得每层都接住。"),
    (253, 'after', "extractSearchText 按模式分流：content 模式给匹配内容本身，其余给文件名列表。英文注释说明 numFiles / numLines / numMatches 是「Found 3 files」类的装饰统计，不进搜索文本（under-count 而非幻影，安全）。"),
    (278, 'after', "content 模式的结果末尾追加翻页信息（limit: 250, offset: 20 这类）——只在真的截断/跳页时出现。模型看到这行就知道该用 offset 续读，而不是重复搜索。"),
    (291, 'after', "count 模式在原始输出后追加一行汇总：Found N occurrences across M files。原始的 filename:count 行保留，汇总行给模型一个不数行数就能引用的总量。"),
    (301, 'after', "files_with_matches 模式空结果同样是「No files found」。三个模式的空结果措辞刻意统一，模型不需要为每个工具记一套空值约定。"),
    (330, 'after', "--hidden：rg 默认跳过隐藏文件，这里显式打开（.github、.env 这类正是搜索目标）。VCS 目录的排除在下一行单独做——开了 hidden 就必须手动挡住 .git 噪音，两个决定是配套的。"),
    (338, 'after', "--max-columns 500：单行超长截断。防止 base64、压缩后的 JS 这类一行几万字符的内容把结果撑爆——搜索结果的行宽上限和 Read 的 2000 字符截断是同一个思路。"),
    (343, 'after', "multiline 旗标只在显式要求时加——rg 的 -U 会改变整个匹配引擎的行为（性能差一个量级），不能默认开。"),
    (360, 'after', "-n 只在 content 模式下传：文件列表模式（-l）根本不输出行号，传了也是浪费。每个旗标都绑定在它有意义的那条分支上。"),
    (376, 'after', "上下文参数的优先级链：context > -C > (-B + -A)。-C/context 是「对称上下文」的捷径，只配了 -B/-A 才分别生效——三层 if/else 把 rg 的参数组合逻辑收拢成一条确定性的规则。"),
    (384, 'after', "pattern 以 - 开头时必须用 -e 传——否则 rg 会把它当成命令行选项解析（搜「--help」这个字符串就挂了）。这是所有 CLI 封装的经典坑，rg 官方推荐的做法就是显式 -e。"),
    (409, 'after', "glob 参数的切分规则：先按空白切，含花括号的片段不再按逗号切（*.{ts,tsx} 里的逗号是 pattern 语法的一部分）。一个不起眼但容易写错的解析器——切错一次，模型的过滤条件就全废。"),
    (427, 'after', "ignore 规则转成 rg 的 --glob '!pattern'。关键在 '**/' 前缀：rg 的 gitignore 语义是相对工作目录的，用户配的相对路径规则必须补 '**/' 才能命中任意深度（注释里附了 ripgrep 上游讨论链接）。绝对路径规则直接加叹号。"),
    (434, 'after', "插件缓存的孤儿版本目录同样排除——和 Glob 底层用的是同一个 getGlobExclusionsForPluginCache。插件升级后旧版本目录还在盘上，不排除的话搜索会把同一个函数的五个旧版本全翻出来。"),
    (441, 'after', "超时设计是最值得学的一处：WSL 上文件读有 3-5 倍性能惩罚，超时交给 rg 自己的 execFile timeout，而不是用 AbortController——注释解释了为什么：AbortController 会打断整个 agent 循环；rg 超时抛 RipgrepTimeoutError 向上传播，模型看到的是「搜索没完成」而不是「没有匹配」。这两种结果的语义差异巨大。"),
    (454, 'after', "content 模式先 head_limit 再转相对路径——顺序是性能优化：宽泛 pattern 可能回 10k+ 行而 limit 只留 30-100 行，先截断就省掉了对将被丢弃的行做逐行字符串处理。"),
    (465, 'after', "行级转相对路径：结果行格式是「绝对路径:内容」，用 indexOf(':') 取第一个冒号劈开。注意 count 模式用的是 lastIndexOf——见下文。"),
    (497, 'after', "count 模式转相对路径用 lastIndexOf(':')——因为行尾是数字计数、路径里也可能含冒号（Windows 盘符），从右往左取才是稳定切分点。和 content 模式的 indexOf 形成对比：两个方向的选取都取决于「哪一侧的字段更可控」。"),
    (531, 'after', "Promise.allSettled 而不是 all：rg 扫描和 stat 之间有时间窗，文件可能在窗口里被删。单个 stat 失败不该让整批结果报废——失败的按 mtime 0 排到最后，自然沉底。"),
    (553, 'after', "排序规则：mtime 降序，文件名做平局裁决。测试环境（NODE_ENV=test）直接按文件名排保证确定性。这就是 Glob 描述里「sorted by modification time」承诺的真正实现处——Glob 和 Grep 的文件列表共用这套排序语义。"),
    (560, 'after', "head_limit 在排序之后应用——「先按新旧排、再取前 N」保证留下的永远是最最近修改的文件，而不是随机的 N 个。这个顺序如果反了，截断就变成抽奖。"),
]
